  const k = a < b ? `${a}\u0000${b}` : `${b}\u0000${a}`; g.edges.set(k, (g.edges.get(k) ?? 0) + 1);
  const t = g.nodes.get(a).text; hebbian(g, [a, b, ...[...g.nodes.keys()].filter((m) => m.length >= minLen && m !== a && m !== b && t.includes(m.toLowerCase()))]);
}

