for (const e of coMentionEpisodes(g)) hebbian(g,e);
decay(g,{factor:0.95,floor:0.05});
const linked = new Set([...g.edges.keys()].flatMap(k=>k.split("\u0000")));
const q = held.filter(r => g.nodes.has(r.from) && g.nodes.has(r.to));
console.log("q", q.length);

const toks = s => new Set(String(s).toLowerCase().split(/[^a-z0-9]+/).filter(w=>w.length>2));
const jac = (a,b) => { let i=0; for (const w of a) if (b.has(w)) i++; const u=a.size+b.size-i; return u?i/u:0; };
const rec = (a,b) => { let i=0; for (const w of a) if (b.has(w)) i++; return a.size?i/a.size:0; };

const R = createRanker(g);
const buckets = { gold:[], top1wrong:[], top1right:[] };
let mentionGold=0, mentionTopWrong=0, wrong=0, right=0;
