  const tgtText = g.nodes.get(r.to).text;
  const mentioned = srcText.includes(r.to.toLowerCase()) || tgtText.includes(r.from.toLowerCase());
  if (mentioned) mentionGold++;
  buckets.gold.push(jac(S,G));
  const t1 = top[0];
  if (t1===r.to) { right++; buckets.top1right.push(jac(S, toks(g.nodes.get(t1).text))); }
  else if (t1) {
    wrong++;
    const tw = toks(g.nodes.get(t1).text);
    buckets.top1wrong.push(jac(S, tw));
    const st = g.nodes.get(r.from).text, tt=g.nodes.get(t1).text;
