  const jw = jac(S, toks(g.nodes.get(top).text));
  if (jg>jw) goldHigher++;
}
console.log({compared, goldHigher});

// relation type distribution of held
const c={};
for (const r of q) c[r.relationType]=(c[r.relationType]??0)+1;
console.log(c);
