import { readFileSync } from "node:fs";
import { loadGraph, hebbian, coMentionEpisodes, decay } from "./artifacts/v2/src/brain/synapse.mjs";
import { createRanker } from "./artifacts/v2/src/brain/context.mjs";

const jsonl = readFileSync("docs/v2/v2-memory.jsonl","utf8");
const lines = jsonl.split("\n").filter(Boolean).map(l=>JSON.parse(l));
const kv = /^([^:]{1,80}):\s*(.+)$/;
// flatten observations in file order
const obs = [];
for (const r of lines) if (r.type==="entity") (r.observations??[]).forEach((o,i)=>obs.push({entity:r.name, text:String(o), i}));
const heldIdx = new Set(obs.map((_,i)=>i).filter(i=>i%5===0));
const held = obs.filter((_,i)=>heldIdx.has(i));
console.log("held obs", held.length);

const questions = held.map((o,qi)=>{
  const m = kv.exec(o.text);
  const relation = m ? m[1].trim() : "note";
  const gold = m ? m[2].trim() : o.text.trim();
  return { question:`What is ${relation} of ${o.entity}?`, entity:o.entity, relation, gold, answerable:true, qi };
});

// remove equal number of entities that are NOT the subject of an answerable question
const subjects = new Set(questions.map(q=>q.entity));
const allEnt = lines.filter(r=>r.type==="entity").map(r=>r.name);
const removable = allEnt.filter(n=>!subjects.has(n)).sort();
const step = Math.max(1, Math.floor(removable.length / questions.length));
const removed = removable.filter((_,i)=>i%step===0).slice(0, questions.length);
console.log("questions", questions.length, "removable", removable.length, "removed", removed.length);
const removedSet = new Set(removed);

// strip held-out observations and removed entities
const heldByEnt = new Map();
for (const o of held) { if (!heldByEnt.has(o.entity)) heldByEnt.set(o.entity, new Set()); heldByEnt.get(o.entity).add(o.text); }
const trainLines = [];
const obsMap = new Map(); // name -> observations remaining
for (const r of lines) {
  if (r.type==="entity") {
    if (removedSet.has(r.name)) continue;
    const drop = heldByEnt.get(r.name) ?? new Set();
    const observations = (r.observations??[]).map(String).filter(o=>!drop.has(o));
    obsMap.set(r.name, observations);
    trainLines.push({...r, observations});
  } else if (r.type==="relation") {
    if (removedSet.has(r.from) || removedSet.has(r.to)) continue;
    trainLines.push(r);
  }
}
const g = loadGraph(trainLines.map(r=>JSON.stringify(r)).join("\n"));
for (const e of coMentionEpisodes(g)) hebbian(g,e); decay(g,{factor:0.95,floor:0.05});

const relOfRemoved = new Map();
for (const r of lines) if (r.type==="relation" && removedSet.has(r.from) && !relOfRemoved.has(r.from)) relOfRemoved.set(r.from, r.relationType);
const unans = removed.map(name=>({
  question:`What is ${relOfRemoved.get(name)??"note"} of ${name}?`,
  entity:name, relation:relOfRemoved.get(name)??"note", gold:null, answerable:false
}));
const all = [...questions, ...unans];
const dev = all.filter((_,i)=>i%2===0);
const test = all.filter((_,i)=>i%2===1);
console.log({dev:dev.length, test:test.length, devA:dev.filter(q=>q.answerable).length, nodes:g.nodes.size});

const norm = s => s.toLowerCase().replace(/\s+/g," ").trim();
function findValue(node, relation) {
  const obs = obsMap.get(node) ?? [];
  const rel = norm(relation);
